// A DRAFT only. Nothing here sends.
const first = $input.first().json;
const body = first.body || first;
const request_id = (typeof body.request_id === 'string' && body.request_id.length <= 100) ? body.request_id : undefined;
const fail = (code, message, status_code = 400) => [{ json: { valid: false, status_code, error: { code, message }, request_id } }];
const isIso = (v) => typeof v === 'string' && v.trim() !== '' && !isNaN(new Date(v).getTime());
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function list(value, required, field) {
  if (value === undefined || value === null || value === '') return required ? { error: field + ' is required' } : { value: '' };
  if (typeof value !== 'string') return { error: field + ' must be comma-separated addresses' };
  const parts = value.split(',').map((s) => s.trim()).filter(Boolean);
  if (required && parts.length === 0) return { error: field + ' is required' };
  for (const x of parts) if (!emailRe.test(x)) return { error: field + ' has an invalid address: ' + JSON.stringify(x) };
  return { value: parts.join(', ') };
}
const to = list(body.to, true, 'to'); if (to.error) return fail('VALIDATION_ERROR', to.error);
const cc = list(body.cc, false, 'cc'); if (cc.error) return fail('VALIDATION_ERROR', cc.error);
const bcc = list(body.bcc, false, 'bcc'); if (bcc.error) return fail('VALIDATION_ERROR', bcc.error);
if (typeof body.subject !== 'string' || body.subject.trim() === '' || body.subject.length > 300) return fail('VALIDATION_ERROR', 'subject must be 1-300 characters');
if (typeof body.body !== 'string' || body.body.trim() === '' || body.body.length > 20000) return fail('VALIDATION_ERROR', 'body must be 1-20000 characters');
let threadId = '';
if (body.threadId != null && body.threadId !== '') {
  if (typeof body.threadId !== 'string' || !/^[A-Za-z0-9]{6,40}$/.test(body.threadId)) return fail('VALIDATION_ERROR', 'threadId is not a Gmail thread id');
  threadId = body.threadId;
}
return [{ json: { valid: true, request_id, to: to.value, cc: cc.value, bcc: bcc.value, subject: body.subject, body: body.body, threadId } }];

const v = $('Validate Input').first().json;
const d = $input.first().json || {};
const message = d.message || {};
return [{ json: { response: { ok: true, request_id: v.request_id, data: {
  status: 'outbox_user_sends', draftId: d.id || null, messageId: message.id || null, threadId: message.threadId || v.threadId || null,
  gmailUrl: 'https://mail.google.com/mail/u/0/#drafts'
} } } }];
